<?php
session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
function e($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$error = ''; $success = ''; $students = []; $recent = [];
try {
  $pdo = new PDO('mysql:host=127.0.0.1;port=3306;dbname=kanji_master;charset=utf8mb4','root','root',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
  // Separate table names leave any existing assignment tables untouched.
  $pdo->exec("CREATE TABLE IF NOT EXISTS teacher_kanji_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, title VARCHAR(150) NOT NULL, instructions TEXT NULL, due_date DATE NULL, pdf_path VARCHAR(500) NULL, pdf_original_name VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (teacher_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  $cols=$pdo->query('SHOW COLUMNS FROM teacher_kanji_assignments')->fetchAll(PDO::FETCH_COLUMN); if(!in_array('pdf_path',$cols,true))$pdo->exec('ALTER TABLE teacher_kanji_assignments ADD COLUMN pdf_path VARCHAR(500) NULL'); if(!in_array('pdf_original_name',$cols,true))$pdo->exec('ALTER TABLE teacher_kanji_assignments ADD COLUMN pdf_original_name VARCHAR(255) NULL');
  $pdo->exec("CREATE TABLE IF NOT EXISTS teacher_kanji_assignment_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, assignment_id BIGINT UNSIGNED NOT NULL, kanji_id INT NOT NULL, UNIQUE KEY uq_tkai (assignment_id,kanji_id), INDEX (kanji_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  $pdo->exec("CREATE TABLE IF NOT EXISTS teacher_kanji_assignment_students (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, assignment_id BIGINT UNSIGNED NOT NULL, student_id INT NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'assigned', submitted_at DATETIME NULL, UNIQUE KEY uq_tkas (assignment_id,student_id), INDEX (student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  $pdo->exec("CREATE TABLE IF NOT EXISTS student_notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, notification_type VARCHAR(40) NOT NULL, title VARCHAR(180) NOT NULL, message VARCHAR(500) NOT NULL, target_url VARCHAR(500) NOT NULL, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_student_notifications_user (user_id, is_read, created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  $role = strtolower((string)($_SESSION['user_role'] ?? ''));
  if (!in_array($role,['teacher','admin'],true)) { http_response_code(403); $error='This page is for teacher or admin accounts only. Your current account role is "'.($role ?: 'not set').'".'; }
  else {
    if ($_SERVER['REQUEST_METHOD']==='POST' && !empty($_POST['assignment_action'])) {
      $token=(string)($_POST['csrf_token']??'');
      $aid=filter_input(INPUT_POST,'assignment_id',FILTER_VALIDATE_INT);
      $action=(string)$_POST['assignment_action'];
      if (empty($_SESSION['csrf_token']) || !hash_equals($_SESSION['csrf_token'],$token)) $error='Your form session expired. Refresh and try again.';
      elseif (!$aid || $aid < 1 || !in_array($action,['delete','update'],true)) $error='Invalid assignment action.';
      else {
        $q=$pdo->prepare('SELECT id,pdf_path FROM teacher_kanji_assignments WHERE id=? AND teacher_id=?');
        $q->execute([$aid,(int)$_SESSION['user_id']]); $owned=$q->fetch();
        if (!$owned) $error='Assignment not found or you do not have permission to change it.';
        elseif ($action==='delete') {
          $pdo->beginTransaction();
          try {
            $q=$pdo->prepare('DELETE FROM teacher_kanji_assignment_students WHERE assignment_id=?'); $q->execute([$aid]);
            $q=$pdo->prepare('DELETE FROM teacher_kanji_assignment_items WHERE assignment_id=?'); $q->execute([$aid]);
            $q=$pdo->prepare('DELETE FROM teacher_kanji_assignments WHERE id=? AND teacher_id=?'); $q->execute([$aid,(int)$_SESSION['user_id']]);
            $pdo->commit();
            if (!empty($owned['pdf_path'])) { $old=__DIR__.DIRECTORY_SEPARATOR.str_replace(['/', '\\'],DIRECTORY_SEPARATOR,$owned['pdf_path']); if (strpos(realpath(dirname($old)) ?: '', realpath(__DIR__.DIRECTORY_SEPARATOR.'uploads'.DIRECTORY_SEPARATOR.'assignments') ?: '___')===0 && is_file($old)) @unlink($old); }
            $success='Assignment deleted.'; $_SESSION['csrf_token']=bin2hex(random_bytes(32));
          } catch(Throwable $t) { if($pdo->inTransaction())$pdo->rollBack(); throw $t; }
        } else {
          $title=trim((string)($_POST['edit_title']??$_POST['title']??'')); $instructions=trim((string)($_POST['edit_instructions']??$_POST['instructions']??'')); $due=trim((string)($_POST['edit_due_date']??$_POST['due_date']??''));
          if ($title==='' || mb_strlen($title)>150) $error='Enter a title up to 150 characters.';
          elseif ($due!=='' && (!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)||!checkdate((int)substr($due,5,2),(int)substr($due,8,2),(int)substr($due,0,4)))) $error='Enter a valid due date.';
          else {
            $pdf=$_FILES['edit_assignment_pdf']??$_FILES['assignment_pdf']??null; $newPath=null; $newOriginal=null;
            if ($pdf && ($pdf['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE) {
              if (($pdf['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK) $error='PDF upload failed.';
              elseif (($pdf['size']??0)>15*1024*1024) $error='The PDF must be 15 MB or smaller.';
              else { $tmp=(string)($pdf['tmp_name']??''); $sig=''; if($tmp!==''&&is_uploaded_file($tmp)){$h=fopen($tmp,'rb');if($h!==false){$sig=(string)fread($h,5);fclose($h);}} if(strtolower(pathinfo((string)($pdf['name']??''),PATHINFO_EXTENSION))!=='pdf'||$sig!=='%PDF-')$error='Please upload a valid PDF file.'; else { $dir=__DIR__.DIRECTORY_SEPARATOR.'uploads'.DIRECTORY_SEPARATOR.'assignments'; if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Could not create upload folder.'); $stored=bin2hex(random_bytes(18)).'.pdf'; if(!move_uploaded_file($tmp,$dir.DIRECTORY_SEPARATOR.$stored))throw new RuntimeException('Could not save the replacement PDF.'); $newPath='uploads/assignments/'.$stored; $newOriginal=basename((string)$pdf['name']); } }
            }
            if($error==='') { $sql='UPDATE teacher_kanji_assignments SET title=?,instructions=?,due_date=?'; $params=[$title,$instructions?:null,$due?:null]; if($newPath!==null){$sql.=',pdf_path=?,pdf_original_name=?';$params[]=$newPath;$params[]=$newOriginal;} $sql.=' WHERE id=? AND teacher_id=?';$params[]=$aid;$params[]=(int)$_SESSION['user_id'];$q=$pdo->prepare($sql);$q->execute($params); if($newPath!==null && !empty($owned['pdf_path'])){$old=__DIR__.DIRECTORY_SEPARATOR.str_replace(['/','\\'],DIRECTORY_SEPARATOR,$owned['pdf_path']);if(is_file($old))@unlink($old);} $success='Assignment updated.';$_SESSION['csrf_token']=bin2hex(random_bytes(32)); }
          }
        }
      }
    }
    if ($_SERVER['REQUEST_METHOD']==='POST' && empty($_POST['assignment_action'])) {
      $token=(string)($_POST['csrf_token']??''); $title=trim((string)($_POST['title']??'')); $instructions=trim((string)($_POST['instructions']??'')); $due=trim((string)($_POST['due_date']??'')); $si=$_POST['student_ids']??[]; $pdf=$_FILES['assignment_pdf']??null;
      if (empty($_SESSION['csrf_token']) || !hash_equals($_SESSION['csrf_token'],$token)) $error='Your form session expired. Refresh and try again.';
      elseif ($title==='' || mb_strlen($title)>150) $error='Enter an assignment title (up to 150 characters).';
      elseif (!$pdf || ($pdf['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK) $error='Please upload a PDF practice worksheet.';
      elseif (($pdf['size']??0)>15*1024*1024) $error='The PDF must be 15 MB or smaller.';
      elseif (!is_array($si)||!$si) $error='Select at least one student.';
      elseif ($due!=='' && (!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)||!checkdate((int)substr($due,5,2),(int)substr($due,8,2),(int)substr($due,0,4)))) $error='Enter a valid due date.';
      else {
        $si=array_values(array_unique(array_filter(array_map('intval',$si),fn($x)=>$x>0)));
        $tmp=(string)($pdf['tmp_name']??''); $isUploaded=$tmp!==''&&is_uploaded_file($tmp); $signature='';
        if($isUploaded){$handle=fopen($tmp,'rb');if($handle!==false){$signature=(string)fread($handle,5);fclose($handle);}}
        if(!$si)$error='Select at least one student.';
        elseif(!$isUploaded||strtolower(pathinfo((string)($pdf['name']??''),PATHINFO_EXTENSION))!=='pdf'||$signature!=='%PDF-')$error='Please upload a valid PDF file.';
        else{$marks=implode(',',array_fill(0,count($si),'?'));$q=$pdo->prepare("SELECT id FROM users WHERE role='student' AND id IN ($marks)");$q->execute($si);$validS=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));
          if(count($validS)!==count($si))$error='Some selected student accounts were not found. Refresh and select again.';
          else{$dir=__DIR__.'/uploads/assignments';if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Could not create upload folder.');$stored=bin2hex(random_bytes(18)).'.pdf';$relative='uploads/assignments/'.$stored;
            if(!move_uploaded_file($tmp,$dir.'/'.$stored))throw new RuntimeException('Could not save PDF. Check folder permissions.');
            $pdo->beginTransaction();try{$q=$pdo->prepare('INSERT INTO teacher_kanji_assignments (teacher_id,title,instructions,due_date,pdf_path,pdf_original_name) VALUES (?,?,?,?,?,?)');$q->execute([(int)$_SESSION['user_id'],$title,$instructions?:null,$due?:null,$relative,basename((string)$pdf['name'])]);$aid=(int)$pdo->lastInsertId();$qs=$pdo->prepare('INSERT INTO teacher_kanji_assignment_students (assignment_id,student_id) VALUES (?,?)');$notice=$pdo->prepare("INSERT INTO student_notifications (user_id, notification_type, title, message, target_url) VALUES (?, 'assignment', ?, ?, ?)");foreach($validS as $id){$qs->execute([$aid,$id]);$notice->execute([(int)$id,'New assignment: '.$title,'Your teacher sent you a new PDF assignment.','student_assignments.php?assignment_id='.(int)$aid]);}$pdo->commit();$success='PDF assignment sent to '.count($validS).' student(s).';$_SESSION['csrf_token']=bin2hex(random_bytes(32));}catch(Throwable $t){if($pdo->inTransaction())$pdo->rollBack();@unlink($dir.'/'.$stored);throw $t;}
          }
        }
      }
    }
    $students=$pdo->query("SELECT id,name,email FROM users WHERE role='student' ORDER BY name")->fetchAll();
    $q=$pdo->prepare('SELECT a.id,a.title,a.instructions,a.due_date,a.created_at,a.pdf_path,a.pdf_original_name,COUNT(DISTINCT s.student_id) student_count FROM teacher_kanji_assignments a LEFT JOIN teacher_kanji_assignment_students s ON s.assignment_id=a.id WHERE a.teacher_id=? GROUP BY a.id,a.title,a.instructions,a.due_date,a.created_at,a.pdf_path,a.pdf_original_name ORDER BY a.created_at DESC LIMIT 10'); $q->execute([(int)$_SESSION['user_id']]); $recent=$q->fetchAll();
  }
} catch(Throwable $t) { error_log('Kanji Master assignment page: '.$t->getMessage()); if($error==='')$error='Could not load the page. Check MAMP MySQL and the users/kanji table columns.'; }
?>
