color:white;font-weight:bold;font-size:15px;cursor:pointer}.notice{padding:12px 14px;border-radius:9px;margin:14px 0}.error{background:#fff0ef;color:#a51d17}.success{background:#eafaf3;color:#087f5b}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:500px}th,td{text-align:left;padding:11px;border-bottom:1px solid var(--line)}th{font-size:12px;color:var(--muted)}.pill{background:#eef0ff;color:var(--accent);padding:4px 8px;border-radius:99px;font-size:12px}.empty{text-align:center;padding:18px;color:var(--muted)}.form-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}.form-heading h2{margin:0}.cancel-button{background:#68748a}.edit-button{padding:8px 12px;font-size:13px;margin-right:5px}.inline-form{display:inline}.delete-button{background:#b42318;padding:8px 11px;font-size:13px}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}header{align-items:flex-start;flex-direction:column}}
</style></head><body><header><div class="brand">日本語 <span>Kanji Master</span> · Teacher</div><nav><a class="nav-back" href="teacher_dashboard.php">← Dashboard</a><a class="active" aria-current="page" href="create_assignment.php">＋ Create assignment</a><a href="teacher_submissions.php">📋 Submissions</a><a href="progress.php">📈 Student progress</a><a href="logout.php">Log out ↗</a></nav></header>
<main><div class="eyebrow">Teacher tools · Step 1</div><h1>Create a kanji assignment</h1><p>Upload a PDF practice worksheet, preview it here, and assign it directly to your students. Existing study and writing-practice pages are not changed.</p>
<?php if($error!==''): ?><div class="notice error"><?=e($error)?></div><?php endif; ?><?php if($success!==''): ?><div class="notice success"><?=e($success)?></div><?php endif; ?>
<?php if(in_array(strtolower((string)($_SESSION['user_role']??'')),['teacher','admin'],true)): ?>
<form method="post" class="panel" id="assignment-form" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e($_SESSION['csrf_token'])?>"><input type="hidden" name="assignment_action" id="assignment_action" value=""><input type="hidden" name="assignment_id" id="assignment_id" value=""><div class="form-heading"><h2 id="form-heading">Create new assignment</h2><button type="button" id="cancel-edit" class="cancel-button" hidden onclick="cancelAssignmentEdit()">Cancel edit</button></div><div class="grid"><div class="field"><label for="title">Assignment title</label><input type="text" id="title" name="title" maxlength="150" required placeholder="N5 Kanji Practice – Week 1"></div><div class="field"><label for="due_date">Due date <span class="hint">(optional)</span></label><input type="date" id="due_date" name="due_date"></div><div class="field full"><label for="instructions">Instructions <span class="hint">(optional)</span></label><textarea id="instructions" name="instructions" maxlength="5000" placeholder="Tell students what to practise."></textarea></div>
<div class="field full"><label for="assignment_pdf">PDF practice worksheet <span class="hint">(required · PDF only · max 15 MB)</span></label><input type="file" id="assignment_pdf" name="assignment_pdf" accept="application/pdf,.pdf" required><div class="pdf-preview-wrap" id="pdf-preview-wrap" hidden><div class="preview-heading"><strong>PDF preview</strong><span id="pdf-file-name"></span></div><iframe id="pdf-preview" title="PDF practice worksheet preview"></iframe></div><p class="hint">Students can open or download this worksheet from their assignments page.</p></div>
<div class="field"><div class="field-title">Assign to students <span class="hint">— at least one</span></div><div class="picker"><div class="picker-tools"><input type="search" id="ss" placeholder="Search name or email"></div><div class="picker-list" id="sl"><?php foreach($students as $s): ?><label class="option" data-search="<?=e(mb_strtolower($s['name'].' '.$s['email']))?>"><input type="checkbox" name="student_ids[]" value="<?=(int)$s['id']?>"><span><strong style="font-size:14px"><?=e($s['name'])?></strong><small><?=e($s['email'])?></small></span></label><?php endforeach; ?><?php if(!$students): ?><div class="empty">No student accounts found. Create student accounts first.</div><?php endif; ?></div></div></div><div class="full"><button type="submit" id="assignment-submit">Create assignment</button></div></div></form>
<section class="panel"><h2>Recent assignments</h2><p>Assignments created by your account.</p><?php if($recent): ?><div class="tablewrap"><table><thead><tr><th>Assignment</th><th>PDF worksheet</th><th>Students</th><th>Due date</th><th>Created</th><th>Manage</th></tr></thead><tbody><?php foreach($recent as $a): ?><tr><td><?=e($a['title'])?></td><td><?php if(!empty($a['pdf_path'])): ?><a href="<?=e($a['pdf_path'])?>" target="_blank" rel="noopener">Preview PDF</a><?php else: ?>No PDF<?php endif; ?></td><td><?=(int)$a['student_count']?></td><td><?=$a['due_date']?e($a['due_date']):'No due date'?></td><td><?=e(date('Y-m-d',strtotime($a['created_at'])))?></td><td><button type="button" class="edit-button" data-edit-assignment data-id="<?=(int)$a['id']?>" data-title="<?=e($a['title'])?>" data-instructions="<?=e($a['instructions']??'')?>" data-due-date="<?=e($a['due_date']??'')?>">Edit</button><form method="post" class="inline-form" onsubmit="return confirm('Delete this assignment for all assigned students? This cannot be undone.');"><input type="hidden" name="csrf_token" value="<?=e($_SESSION['csrf_token'])?>"><input type="hidden" name="assignment_action" value="delete"><input type="hidden" name="assignment_id" value="<?=(int)$a['id']?>"><button type="submit" class="delete-button">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No assignments created yet.</div><?php endif; ?></section><?php endif; ?></main>
<style>.pdf-preview-wrap{margin-top:12px;border:1px solid var(--line);border-radius:10px;overflow:hidden}.preview-heading{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:10px 12px;background:#f8f9fd}.preview-heading span{font-weight:normal;color:var(--muted);font-size:13px}#pdf-preview{display:block;width:100%;height:520px;border:0;background:#eef1f7}input[type=file]{width:100%;padding:12px;border:1px dashed #aeb8ce;border-radius:9px;background:#fafbff}@media(max-width:700px){#pdf-preview{height:380px}}</style><script>function filter(inputId,listId){const i=document.getElementById(inputId),l=document.getElementById(listId);if(!i||!l)return;i.addEventListener('input',()=>{const q=i.value.trim().toLocaleLowerCase();l.querySelectorAll('.option').forEach(o=>o.hidden=!o.dataset.search.includes(q));});}filter('ss','sl');const f=document.getElementById('assignment_pdf');f?.addEventListener('change',()=>{const file=f.files&&f.files[0],w=document.getElementById('pdf-preview-wrap'),frame=document.getElementById('pdf-preview');if(!file){w.hidden=true;return;}if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){alert('Please choose a PDF file.');f.value='';w.hidden=true;return;}if(frame.dataset.url)URL.revokeObjectURL(frame.dataset.url);const u=URL.createObjectURL(file);frame.src=u;frame.dataset.url=u;document.getElementById('pdf-file-name').textContent=file.name;w.hidden=false;});document.querySelectorAll('[data-edit-assignment]').forEach(button=>{button.addEventListener('click',()=>{const form=document.getElementById('assignment-form');document.getElementById('title').value=button.dataset.title||'';document.getElementById('instructions').value=button.dataset.instructions||'';document.getElementById('due_date').value=button.dataset.dueDate||'';document.getElementById('assignment_action').value='update';document.getElementById('assignment_id').value=button.dataset.id||'';document.getElementById('form-heading').textContent='Edit assignment';document.getElementById('assignment-submit').textContent='Save changes';document.getElementById('cancel-edit').hidden=false;const pdf=document.getElementById('assignment_pdf');pdf.required=false;pdf.value='';document.getElementById('pdf-preview-wrap').hidden=true;form.scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('title').focus();});});function cancelAssignmentEdit(){const form=document.getElementById('assignment-form');form.reset();document.getElementById('assignment_action').value='';document.getElementById('assignment_id').value='';document.getElementById('form-heading').textContent='Create new assignment';document.getElementById('assignment-submit').textContent='Create assignment';document.getElementById('cancel-edit').hidden=true;document.getElementById('assignment_pdf').required=true;document.getElementById('pdf-preview-wrap').hidden=true;}</script></body></html>
